// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        Reverter r = new Reverter();

        // deposit: credit the reverter caller via the fallback
        vm.deal(address(r), amount);
        vm.prank(address(r));
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk);

        // withdraw from the reverter caller: the low-level call must fail,
        // so the reference withdraw reverts; the mutant swallows it.
        vm.prank(address(r));
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
